"""Arbrume for Blender: procedural trees and plants generated by the ``arbrume`` wheel.

Registration builds the species parameter properties and panels from the species data of
the installed wheel (see ``logic.schema``), so parameters added to the generator appear
without a change here. ``unregister`` removes everything ``register`` added, so the
extension can be disabled, enabled and reloaded in one session.
"""

from __future__ import annotations

import bpy
from bpy.app.handlers import persistent
from bpy.props import PointerProperty

import arbrume

from . import curves_ui, ops, prefs, props, ui
from .logic import species
from .state import STATE, reset

_REGISTERED: list[type] = []


@persistent
def arbrume_on_load(_scene) -> None:
    """Forgets the session state of the previous file."""
    reset()


def _load_schema() -> None:
    try:
        STATE.presets = list(arbrume.presets())
        STATE.sections = species.preset_schema()
        STATE.schema_error = ""
    except (ValueError, TypeError, OSError, RuntimeError, KeyError) as error:
        STATE.sections = []
        STATE.schema_error = f"Species parameters unavailable: {error}"
    STATE.specs = {spec.path: spec for s in STATE.sections for spec in s.params()}


def _register(cls: type) -> None:
    bpy.utils.register_class(cls)
    _REGISTERED.append(cls)


def _remove_handlers() -> None:
    handlers = bpy.app.handlers.load_post
    for handler in [h for h in handlers if getattr(h, "__name__", "") == "arbrume_on_load"]:
        handlers.remove(handler)


def register() -> None:
    """Registers classes, properties, the Add menu entry, the load handler and the timer."""
    _load_schema()
    _register(prefs.ARBRUME_AP_preferences)
    _register(props.ARBRUME_PG_plant)
    params_class = props.build_params_class(STATE.sections)
    _register(params_class)
    props.attach_params(params_class)
    bpy.types.Object.arbrume = PointerProperty(type=props.ARBRUME_PG_plant)
    for cls in ops.CLASSES:
        _register(cls)
    _register(ui.VIEW3D_PT_arbrume)
    for section in STATE.sections:
        _register(ui.make_section_panel(section))
    _register(ui.VIEW3D_PT_arbrume_tools)
    bpy.types.VIEW3D_MT_mesh_add.append(ui.menu_add)
    _remove_handlers()
    bpy.app.handlers.load_post.append(arbrume_on_load)
    curves_ui.register()


def unregister() -> None:
    """Removes everything :func:`register` added."""
    curves_ui.unregister()
    _remove_handlers()
    bpy.types.VIEW3D_MT_mesh_add.remove(ui.menu_add)
    if hasattr(bpy.types.Object, "arbrume"):
        del bpy.types.Object.arbrume
    props.detach_params()
    for cls in reversed(_REGISTERED):
        bpy.utils.unregister_class(cls)
    _REGISTERED.clear()
    reset()
    STATE.sections, STATE.specs, STATE.presets = [], {}, []
    props.clear_enum_cache()
